import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.BCAjmnCN.js";const u=JSON.parse('{"title":"深夜碎碎念：代码、孤独与热爱","description":"","frontmatter":{"title":"深夜碎碎念：代码、孤独与热爱","date":"2026-06-20T00:00:00.000Z","category":"随笔","tags":["随笔","思考"]},"headers":[],"relativePath":"posts/late-night-thoughts.md","filePath":"posts/late-night-thoughts.md","lastUpdated":1782374328000}'),p={name:"posts/late-night-thoughts.md"};function h(s,a,i,l,n,d){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="深夜碎碎念-代码、孤独与热爱" tabindex="-1">深夜碎碎念：代码、孤独与热爱 <a class="header-anchor" href="#深夜碎碎念-代码、孤独与热爱" aria-label="Permalink to &quot;深夜碎碎念：代码、孤独与热爱&quot;">​</a></h1><p>凌晨一点，屏幕的蓝光把房间照得像个水族箱。数字雨在博客背景上下落，我自己也像那一行行字符，安静地往下坠。</p><p>写代码的人大概都熟悉这种时刻。白天的喧嚣退去，世界只剩你和终端里闪烁的光标。这是一种孤独，但不是令人难过的那种——更像深夜独自走在空旷街道上的那种，清冷，但自由。</p><h2 id="孤独是创作的代价" tabindex="-1">孤独是创作的代价 <a class="header-anchor" href="#孤独是创作的代价" aria-label="Permalink to &quot;孤独是创作的代价&quot;">​</a></h2><p>我常想，为什么技术人总爱熬夜。不是效率高，是夜里没有打断。没有消息弹窗，没有会议提醒，没有「能不能帮我看个问题」。只有你和要解决的那个问题，一对一，像决斗。</p><p>这种专注是稀缺的。白天我们被切碎成无数个五分钟，夜里才重新拼回完整的自己。</p><p>所以熬夜写代码的人，不一定是工作狂，可能只是想找回一段不被打扰的时间，做点自己真正想做的东西。这个博客就是这样的产物——没人要求我做，没人为它付费，但我想有一个角落，装下我那些乱七八糟的念头和折腾出来的小玩意。</p><h2 id="热爱是孤独的解药" tabindex="-1">热爱是孤独的解药 <a class="header-anchor" href="#热爱是孤独的解药" aria-label="Permalink to &quot;热爱是孤独的解药&quot;">​</a></h2><p>但孤独久了会钝。技术本身是冷的，代码不会回应你的情绪。一个 Bug 修好了，它不会说谢谢；一个功能上线了，它不会鼓掌。如果只盯着屏幕，人会慢慢干掉。</p><p>我后来发现，热爱需要出口。不只是写出来，还要被看见。哪怕只是一个人在某个深夜偶然路过我的博客，读了一行，会心一笑——那个瞬间，孤独就被打破了一秒钟。</p><p>所以我们写博客、开源项目、发推文。不只是炫耀成果，更是扔出一个漂流瓶，期待某个频率相同的人捡到。</p><h2 id="技术是连接-不是隔离" tabindex="-1">技术是连接，不是隔离 <a class="header-anchor" href="#技术是连接-不是隔离" aria-label="Permalink to &quot;技术是连接，不是隔离&quot;">​</a></h2><p>有人说技术让人疏远。我倒觉得，技术是最容易让人连接的东西之一。</p><p>一段开源代码，可能是地球另一边某个失眠的人深夜写的。你 clone 下来，跑通了，那一刻你们隔着时区握了下手。这种连接比社交网络上点赞真实得多——它建立在「我理解你写了什么」之上。</p><p>我希望这个博客也能成为这样的连接点。不只是技术笔记，也是一个人存在过的痕迹。如果你读到这里，恰好也喜欢深夜写代码，那我们算是隔空打过招呼了。</p><h2 id="写在最后" tabindex="-1">写在最后 <a class="header-anchor" href="#写在最后" aria-label="Permalink to &quot;写在最后&quot;">​</a></h2><p>夜更深了。光标还在闪，数字雨还在落。该睡了。</p><p>明天还有明天的 Bug，明天的代码，明天的深夜碎碎念。但今晚这篇就到这里。</p><p>晚安，陌生的同行者。</p>',19)])])}const _=t(p,[["render",h]]);export{u as __pageData,_ as default};
